import React, { useState, useRef, useEffect, useCallback } from "react";

// ---- Chart data (auto-generated from real onset/spectral analysis of the track) ----
// Each entry: [timeInSeconds, lane(0-3)]
const NOTE_DATA = [[0.186, 3], [0.418, 2], [0.65, 3], [0.882, 1], [1.115, 3], [1.277, 0], [1.579, 2], [1.811, 0], [2.043, 2], [2.276, 0], [2.508, 3], [2.74, 0], [2.972, 2], [3.111, 1], [3.413, 3], [3.646, 1], [3.878, 2], [4.11, 1], [4.342, 3], [4.574, 1], [4.807, 3], [4.969, 0], [5.271, 2], [5.503, 1], [5.735, 2], [5.968, 1], [6.2, 3], [6.432, 0], [6.664, 2], [6.803, 1], [7.105, 3], [7.338, 0], [7.57, 3], [7.802, 1], [8.034, 3], [8.266, 2], [8.499, 3], [8.661, 0], [8.963, 2], [9.195, 0], [9.427, 2], [9.66, 1], [9.892, 3], [10.124, 0], [10.356, 2], [10.495, 1], [10.797, 3], [11.029, 1], [11.262, 2], [11.494, 1], [11.726, 3], [11.958, 1], [12.19, 2], [12.353, 0], [12.655, 2], [12.887, 1], [13.119, 2], [13.351, 1], [13.584, 3], [13.816, 0], [14.048, 2], [14.187, 0], [14.489, 3], [14.745, 0], [14.954, 2], [15.186, 1], [15.418, 3], [15.65, 1], [15.882, 2], [16.045, 0], [16.347, 2], [16.579, 0], [16.811, 3], [17.043, 1], [17.276, 2], [17.508, 0], [17.74, 2], [17.879, 0], [18.204, 1], [18.437, 0], [18.646, 3], [18.878, 1], [19.11, 3], [19.342, 1], [19.574, 3], [19.737, 0], [20.039, 2], [20.271, 1], [20.503, 3], [20.735, 1], [20.968, 3], [21.2, 0], [21.432, 2], [21.664, 0], [21.896, 0], [22.059, 0]];

const AUDIO_SRC = "data:audio/mpeg;base64,";

const LANE_KEYS = ["D", "F", "J", "K"];
const LANE_COLORS = ["#C9A24B", "#B5673A", "#7A8B6F", "#5E7C8A"]; // brass, rust, sage, slate-teal
const LEAD_TIME = 1.9; // seconds a note is visible before it must be hit
const HIT_Y = 82; // percent from top where the hit line sits
const WINDOW_PERFECT = 0.07;
const WINDOW_GOOD = 0.15;
const WINDOW_MISS = 0.22;

function judge(dt) {
  const a = Math.abs(dt);
  if (a <= WINDOW_PERFECT) return "PERFECT";
  if (a <= WINDOW_GOOD) return "GOOD";
  if (a <= WINDOW_MISS) return "OK";
  return null;
}

export default function JitterbugRhythm() {
  const [phase, setPhase] = useState("intro"); // intro | playing | result
  const [now, setNow] = useState(0);
  const [score, setScore] = useState(0);
  const [combo, setCombo] = useState(0);
  const [maxCombo, setMaxCombo] = useState(0);
  const [judgeCounts, setJudgeCounts] = useState({ PERFECT: 0, GOOD: 0, OK: 0, MISS: 0 });
  const [popups, setPopups] = useState([]); // floating judgement text per lane
  const [flashLane, setFlashLane] = useState([false, false, false, false]);
  const [glow, setGlow] = useState("");

  const audioRef = useRef(null);
  const notesRef = useRef([]); // mutable working copy: {t, lane, hit, missed}
  const rafRef = useRef(null);
  const startAtRef = useRef(0);
  const popupIdRef = useRef(0);

  useEffect(() => {
    notesRef.current = NOTE_DATA.map(([t, lane], i) => ({
      id: i,
      t,
      lane,
      hit: false,
      missed: false,
    }));
  }, []);

  const tick = useCallback(() => {
    const audio = audioRef.current;
    if (!audio) return;
    const t = audio.currentTime;
    setNow(t);

    // auto-miss notes that scrolled past the miss window
    let missedThisFrame = 0;
    notesRef.current.forEach((n) => {
      if (!n.hit && !n.missed && t - n.t > WINDOW_MISS) {
        n.missed = true;
        missedThisFrame++;
      }
    });
    if (missedThisFrame > 0) {
      setCombo(0);
      setJudgeCounts((jc) => ({ ...jc, MISS: jc.MISS + missedThisFrame }));
    }

    if (audio.ended || t >= audio.duration - 0.05) {
      setPhase("result");
      return;
    }
    rafRef.current = requestAnimationFrame(tick);
  }, []);

  const start = () => {
    setScore(0);
    setCombo(0);
    setMaxCombo(0);
    setJudgeCounts({ PERFECT: 0, GOOD: 0, OK: 0, MISS: 0 });
    notesRef.current = NOTE_DATA.map(([t, lane], i) => ({ id: i, t, lane, hit: false, missed: false }));
    setPhase("playing");
    const audio = audioRef.current;
    if (audio) {
      audio.currentTime = 0;
      audio.play();
      startAtRef.current = performance.now();
      rafRef.current = requestAnimationFrame(tick);
    }
  };

  useEffect(() => {
    return () => {
      if (rafRef.current) cancelAnimationFrame(rafRef.current);
    };
  }, []);

  const spawnPopup = (lane, text, color) => {
    const id = popupIdRef.current++;
    setPopups((p) => [...p, { id, lane, text, color }]);
    setTimeout(() => {
      setPopups((p) => p.filter((x) => x.id !== id));
    }, 420);
  };

  const pressLane = useCallback(
    (lane) => {
      if (phase !== "playing") return;
      const audio = audioRef.current;
      if (!audio) return;
      const t = audio.currentTime;

      setFlashLane((f) => {
        const nf = [...f];
        nf[lane] = true;
        return nf;
      });
      setTimeout(() => {
        setFlashLane((f) => {
          const nf = [...f];
          nf[lane] = false;
          return nf;
        });
      }, 100);

      // find nearest un-hit, un-missed note in this lane
      let best = null;
      let bestDt = Infinity;
      for (const n of notesRef.current) {
        if (n.lane !== lane || n.hit || n.missed) continue;
        const dt = t - n.t;
        if (Math.abs(dt) < Math.abs(bestDt)) {
          bestDt = dt;
          best = n;
        }
      }

      if (best && Math.abs(bestDt) <= WINDOW_MISS) {
        const result = judge(bestDt);
        best.hit = true;
        if (result === "PERFECT") {
          setScore((s) => s + 300);
          setCombo((c) => {
            const nc = c + 1;
            setMaxCombo((m) => Math.max(m, nc));
            return nc;
          });
          spawnPopup(lane, "PERFECT", LANE_COLORS[lane]);
          setJudgeCounts((jc) => ({ ...jc, PERFECT: jc.PERFECT + 1 }));
        } else if (result === "GOOD") {
          setScore((s) => s + 150);
          setCombo((c) => {
            const nc = c + 1;
            setMaxCombo((m) => Math.max(m, nc));
            return nc;
          });
          spawnPopup(lane, "GOOD", LANE_COLORS[lane]);
          setJudgeCounts((jc) => ({ ...jc, GOOD: jc.GOOD + 1 }));
        } else {
          setScore((s) => s + 50);
          setCombo((c) => {
            const nc = c + 1;
            setMaxCombo((m) => Math.max(m, nc));
            return nc;
          });
          spawnPopup(lane, "OK", "#8a8a8a");
          setJudgeCounts((jc) => ({ ...jc, OK: jc.OK + 1 }));
        }
      } else {
        // empty press -> small whiff, no combo break in this style (forgiving), but flash miss text softly
        spawnPopup(lane, "-", "#555");
      }
    },
    [phase]
  );

  useEffect(() => {
    const handler = (e) => {
      const idx = LANE_KEYS.indexOf(e.key.toUpperCase());
      if (idx !== -1) {
        e.preventDefault();
        pressLane(idx);
      }
      if (e.key === " " && phase !== "playing") {
        e.preventDefault();
        start();
      }
    };
    window.addEventListener("keydown", handler);
    return () => window.removeEventListener("keydown", handler);
  }, [pressLane, phase]);

  const total =
    judgeCounts.PERFECT + judgeCounts.GOOD + judgeCounts.OK + judgeCounts.MISS;
  const accuracy =
    total > 0
      ? (
          ((judgeCounts.PERFECT * 300 + judgeCounts.GOOD * 150 + judgeCounts.OK * 50) /
            (total * 300)) *
          100
        ).toFixed(1)
      : "0.0";

  let rank = "C";
  const acc = parseFloat(accuracy);
  if (acc >= 95) rank = "S";
  else if (acc >= 88) rank = "A";
  else if (acc >= 75) rank = "B";

  return (
    <div
      style={{
        width: "100%",
        height: "100vh",
        minHeight: 640,
        background:
          "radial-gradient(ellipse at 50% -10%, #1c2430 0%, #10141c 55%, #0a0d13 100%)",
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
        justifyContent: "center",
        fontFamily:
          "'Georgia', 'Times New Roman', serif",
        color: "#EDE3D0",
        position: "relative",
        overflow: "hidden",
        userSelect: "none",
      }}
    >
      <audio ref={audioRef} src={AUDIO_SRC} preload="auto" />

      {/* deco corner ornaments */}
      <DecoCorner corner="tl" />
      <DecoCorner corner="tr" />
      <DecoCorner corner="bl" />
      <DecoCorner corner="br" />

      {phase === "intro" && <IntroScreen onStart={start} />}

      {phase === "playing" && (
        <PlayingScreen
          now={now}
          score={score}
          combo={combo}
          notesRef={notesRef}
          popups={popups}
          flashLane={flashLane}
          onLaneClick={pressLane}
        />
      )}

      {phase === "result" && (
        <ResultScreen
          score={score}
          maxCombo={maxCombo}
          judgeCounts={judgeCounts}
          accuracy={accuracy}
          rank={rank}
          onRetry={start}
        />
      )}
    </div>
  );
}

function DecoCorner({ corner }) {
  const pos = {
    tl: { top: 14, left: 14 },
    tr: { top: 14, right: 14, transform: "scaleX(-1)" },
    bl: { bottom: 14, left: 14, transform: "scaleY(-1)" },
    br: { bottom: 14, right: 14, transform: "scale(-1,-1)" },
  }[corner];
  return (
    <svg
      width="64"
      height="64"
      viewBox="0 0 64 64"
      style={{ position: "absolute", opacity: 0.35, ...pos }}
    >
      <path
        d="M2 2 H30 M2 2 V30"
        stroke="#C9A24B"
        strokeWidth="2"
        fill="none"
      />
      <path
        d="M10 2 L2 10"
        stroke="#C9A24B"
        strokeWidth="1.5"
        fill="none"
      />
      <circle cx="2" cy="2" r="3" fill="#C9A24B" />
    </svg>
  );
}

function IntroScreen({ onStart }) {
  return (
    <div style={{ textAlign: "center", padding: 24, zIndex: 2 }}>
      <div
        style={{
          fontSize: 13,
          letterSpacing: 6,
          color: "#C9A24B",
          marginBottom: 10,
          textTransform: "uppercase",
        }}
      >
        A Tribute in Four Steps
      </div>
      <h1
        style={{
          fontSize: "clamp(32px, 6vw, 56px)",
          margin: "0 0 6px",
          fontWeight: 700,
          letterSpacing: 1,
          color: "#F3E9D2",
          textShadow: "0 0 24px rgba(201,162,75,0.35)",
        }}
      >
        The Ol&apos; Jitterbug
      </h1>
      <div style={{ fontSize: 15, color: "#9AA5B1", marginBottom: 36 }}>
        22초짜리 스윙 리듬 게임 · 물풍선 대신 발끝으로
      </div>

      <div
        style={{
          display: "flex",
          gap: 14,
          justifyContent: "center",
          marginBottom: 40,
        }}
      >
        {LANE_KEYS.map((k, i) => (
          <div
            key={k}
            style={{
              width: 54,
              height: 54,
              borderRadius: 8,
              border: `2px solid ${LANE_COLORS[i]}`,
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              fontSize: 20,
              fontWeight: 700,
              color: LANE_COLORS[i],
              boxShadow: `0 0 14px ${LANE_COLORS[i]}55`,
            }}
          >
            {k}
          </div>
        ))}
      </div>

      <button
        onClick={onStart}
        style={{
          background: "linear-gradient(180deg,#D9B968,#B5893A)",
          color: "#1a1305",
          border: "none",
          padding: "14px 38px",
          fontSize: 17,
          fontWeight: 700,
          letterSpacing: 2,
          borderRadius: 4,
          cursor: "pointer",
          boxShadow: "0 6px 0 #7a5c22, 0 10px 20px rgba(0,0,0,0.4)",
        }}
      >
        START (Space)
      </button>
      <div style={{ marginTop: 18, fontSize: 12, color: "#6b7480" }}>
        D · F · J · K 키로 노트가 라인에 닿는 순간을 맞춰보세요
      </div>
    </div>
  );
}

function PlayingScreen({ now, score, combo, notesRef, popups, flashLane, onLaneClick }) {
  const visibleNotes = notesRef.current.filter(
    (n) => !n.hit && n.t - now <= LEAD_TIME && n.t - now >= -0.3
  );

  return (
    <div
      style={{
        width: "100%",
        maxWidth: 480,
        height: "100%",
        maxHeight: 720,
        position: "relative",
        zIndex: 2,
      }}
    >
      {/* HUD */}
      <div
        style={{
          position: "absolute",
          top: 18,
          left: 0,
          right: 0,
          display: "flex",
          justifyContent: "space-between",
          padding: "0 18px",
          zIndex: 5,
        }}
      >
        <div>
          <div style={{ fontSize: 11, color: "#9AA5B1", letterSpacing: 2 }}>SCORE</div>
          <div style={{ fontSize: 26, fontWeight: 700, color: "#F3E9D2" }}>
            {score.toLocaleString()}
          </div>
        </div>
        <div style={{ textAlign: "right" }}>
          <div style={{ fontSize: 11, color: "#9AA5B1", letterSpacing: 2 }}>COMBO</div>
          <div
            style={{
              fontSize: 26,
              fontWeight: 700,
              color: combo > 0 ? "#C9A24B" : "#5b6169",
            }}
          >
            {combo}
          </div>
        </div>
      </div>

      {/* lanes */}
      <div
        style={{
          position: "absolute",
          top: 70,
          bottom: 0,
          left: 0,
          right: 0,
          display: "flex",
        }}
      >
        {LANE_KEYS.map((key, lane) => (
          <div
            key={lane}
            onClick={() => onLaneClick(lane)}
            style={{
              flex: 1,
              position: "relative",
              borderLeft: lane === 0 ? "none" : "1px solid rgba(255,255,255,0.06)",
              background: flashLane[lane]
                ? `linear-gradient(180deg, transparent, ${LANE_COLORS[lane]}22)`
                : "transparent",
              cursor: "pointer",
            }}
          >
            {/* hit line */}
            <div
              style={{
                position: "absolute",
                top: `${HIT_Y}%`,
                left: 4,
                right: 4,
                height: 4,
                background: flashLane[lane] ? LANE_COLORS[lane] : "rgba(201,162,75,0.35)",
                borderRadius: 2,
                boxShadow: flashLane[lane] ? `0 0 16px ${LANE_COLORS[lane]}` : "none",
                transition: "background 0.06s, box-shadow 0.06s",
              }}
            />
            {/* key label */}
            <div
              style={{
                position: "absolute",
                top: `calc(${HIT_Y}% + 12px)`,
                left: "50%",
                transform: "translateX(-50%)",
                fontSize: 13,
                fontWeight: 700,
                color: LANE_COLORS[lane],
                opacity: 0.75,
              }}
            >
              {key}
            </div>

            {/* falling notes */}
            {visibleNotes
              .filter((n) => n.lane === lane)
              .map((n) => {
                const progress = 1 - (n.t - now) / LEAD_TIME; // 0 at spawn, 1 at hit line
                const topPct = progress * HIT_Y;
                return (
                  <div
                    key={n.id}
                    style={{
                      position: "absolute",
                      top: `${topPct}%`,
                      left: 6,
                      right: 6,
                      height: 16,
                      borderRadius: 4,
                      background: `linear-gradient(180deg, ${LANE_COLORS[lane]}, ${LANE_COLORS[lane]}cc)`,
                      boxShadow: `0 0 10px ${LANE_COLORS[lane]}99`,
                      border: "1px solid rgba(255,255,255,0.25)",
                    }}
                  />
                );
              })}

            {/* judgement popups */}
            {popups
              .filter((p) => p.lane === lane)
              .map((p) => (
                <div
                  key={p.id}
                  style={{
                    position: "absolute",
                    top: `calc(${HIT_Y}% - 34px)`,
                    left: "50%",
                    transform: "translateX(-50%)",
                    fontSize: 13,
                    fontWeight: 700,
                    letterSpacing: 1,
                    color: p.color,
                    textShadow: "0 0 8px rgba(0,0,0,0.6)",
                    animation: "floatUp 0.42s ease-out forwards",
                    pointerEvents: "none",
                  }}
                >
                  {p.text}
                </div>
              ))}
          </div>
        ))}
      </div>

      <style>{`
        @keyframes floatUp {
          0% { opacity: 1; transform: translate(-50%, 0); }
          100% { opacity: 0; transform: translate(-50%, -18px); }
        }
      `}</style>
    </div>
  );
}

function ResultScreen({ score, maxCombo, judgeCounts, accuracy, rank, onRetry }) {
  return (
    <div style={{ textAlign: "center", padding: 24, zIndex: 2 }}>
      <div style={{ fontSize: 13, letterSpacing: 6, color: "#C9A24B", marginBottom: 6 }}>
        CURTAIN CALL
      </div>
      <div
        style={{
          fontSize: 72,
          fontWeight: 700,
          color: "#F3E9D2",
          textShadow: "0 0 30px rgba(201,162,75,0.4)",
          marginBottom: 4,
        }}
      >
        {rank}
      </div>
      <div style={{ fontSize: 15, color: "#9AA5B1", marginBottom: 26 }}>
        정확도 {accuracy}%
      </div>

      <div
        style={{
          display: "inline-grid",
          gridTemplateColumns: "auto auto",
          rowGap: 8,
          columnGap: 24,
          fontSize: 14,
          color: "#c8ccd2",
          marginBottom: 30,
          textAlign: "left",
        }}
      >
        <div style={{ color: "#9AA5B1" }}>SCORE</div>
        <div style={{ fontWeight: 700, color: "#F3E9D2" }}>{score.toLocaleString()}</div>
        <div style={{ color: "#9AA5B1" }}>MAX COMBO</div>
        <div style={{ fontWeight: 700, color: "#F3E9D2" }}>{maxCombo}</div>
        <div style={{ color: "#C9A24B" }}>PERFECT</div>
        <div>{judgeCounts.PERFECT}</div>
        <div style={{ color: "#B5673A" }}>GOOD</div>
        <div>{judgeCounts.GOOD}</div>
        <div style={{ color: "#8a8a8a" }}>OK</div>
        <div>{judgeCounts.OK}</div>
        <div style={{ color: "#6b7480" }}>MISS</div>
        <div>{judgeCounts.MISS}</div>
      </div>

      <div>
        <button
          onClick={onRetry}
          style={{
            background: "linear-gradient(180deg,#D9B968,#B5893A)",
            color: "#1a1305",
            border: "none",
            padding: "12px 32px",
            fontSize: 15,
            fontWeight: 700,
            letterSpacing: 2,
            borderRadius: 4,
            cursor: "pointer",
            boxShadow: "0 6px 0 #7a5c22, 0 10px 20px rgba(0,0,0,0.4)",
          }}
        >
          다시 추기 (Space)
        </button>
      </div>
    </div>
  );
}
